PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS facilities (id TEXT PRIMARY KEY, external_code TEXT UNIQUE, name TEXT NOT NULL, oblast TEXT NOT NULL DEFAULT 'Тернопільська', district TEXT, hromada TEXT, settlement TEXT, facility_type TEXT, is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS import_batches (id TEXT PRIMARY KEY, source_type TEXT NOT NULL CHECK (source_type IN ('excel','google_sheets','manual','api')), source_name TEXT, status TEXT NOT NULL CHECK (status IN ('pending','validated','committed','failed','rejected')), rows_received INTEGER NOT NULL DEFAULT 0, rows_inserted INTEGER NOT NULL DEFAULT 0, rows_updated INTEGER NOT NULL DEFAULT 0, rows_rejected INTEGER NOT NULL DEFAULT 0, validation_summary TEXT, created_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);
CREATE TABLE IF NOT EXISTS isolates (id TEXT PRIMARY KEY, facility_id TEXT REFERENCES facilities(id), sample_id TEXT NOT NULL, isolate_code TEXT, pseudonymous_patient_id TEXT, sampling_date TEXT, sample_matrix_type TEXT, bacterial_species TEXT NOT NULL, hromada TEXT, settlement TEXT, source_batch_id TEXT REFERENCES import_batches(id), source_system TEXT NOT NULL DEFAULT 'manual', source_record_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(source_system, source_record_id));
CREATE INDEX IF NOT EXISTS idx_isolates_sample_id ON isolates(sample_id);
CREATE INDEX IF NOT EXISTS idx_isolates_species ON isolates(bacterial_species);
CREATE INDEX IF NOT EXISTS idx_isolates_sampling_date ON isolates(sampling_date);
CREATE INDEX IF NOT EXISTS idx_isolates_hromada ON isolates(hromada);
CREATE TABLE IF NOT EXISTS ast_results (id TEXT PRIMARY KEY, isolate_id TEXT NOT NULL REFERENCES isolates(id) ON DELETE CASCADE, antimicrobial_agent TEXT NOT NULL, mic_operator TEXT, mic_value TEXT, zone_diameter TEXT, sir_category TEXT CHECK (sir_category IN ('S','I','R') OR sir_category IS NULL), interpretation_standard TEXT, source_batch_id TEXT REFERENCES import_batches(id), source_system TEXT NOT NULL DEFAULT 'manual', source_record_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(source_system, source_record_id));
CREATE INDEX IF NOT EXISTS idx_ast_agent ON ast_results(antimicrobial_agent);
CREATE INDEX IF NOT EXISTS idx_ast_sir ON ast_results(sir_category);
CREATE INDEX IF NOT EXISTS idx_ast_isolate ON ast_results(isolate_id);
CREATE TABLE IF NOT EXISTS wgs_results (id TEXT PRIMARY KEY, isolate_id TEXT NOT NULL REFERENCES isolates(id) ON DELETE CASCADE, sequencing_date TEXT, sequencing_platform TEXT, mlst_st TEXT, serotype_k_o_antigen TEXT, amr_genotype_genes TEXT, point_mutations TEXT, virulence_genes TEXT, plasmid_replicon_type TEXT, fasta_fastq_object_key TEXT, source_batch_id TEXT REFERENCES import_batches(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(isolate_id));
CREATE TABLE IF NOT EXISTS ipc_visits (id TEXT PRIMARY KEY, facility_id TEXT NOT NULL REFERENCES facilities(id), planned_month TEXT, visit_date TEXT, responsible_person TEXT, status TEXT NOT NULL DEFAULT 'planned', summary TEXT, source_batch_id TEXT REFERENCES import_batches(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ipc_assessments (id TEXT PRIMARY KEY, visit_id TEXT NOT NULL REFERENCES ipc_visits(id) ON DELETE CASCADE, form_version TEXT, criterion_code TEXT NOT NULL, criterion_name TEXT, result TEXT, score REAL, comment TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS recommendations (id TEXT PRIMARY KEY, facility_id TEXT NOT NULL REFERENCES facilities(id), visit_id TEXT REFERENCES ipc_visits(id), description TEXT NOT NULL, responsible_person TEXT, due_date TEXT, status TEXT NOT NULL DEFAULT 'open', completion_note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS legal_acts (id TEXT PRIMARY KEY, title TEXT NOT NULL, document_number TEXT, document_date TEXT, source_url TEXT, status TEXT, effective_from TEXT, checked_at TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS external_sync_runs (id TEXT PRIMARY KEY, provider TEXT NOT NULL CHECK (provider IN ('google_sheets')), spreadsheet_id TEXT NOT NULL, sheet_name TEXT, direction TEXT NOT NULL DEFAULT 'inbound' CHECK (direction IN ('inbound','outbound','bidirectional')), status TEXT NOT NULL CHECK (status IN ('pending','running','success','partial','failed')), cursor_value TEXT, rows_read INTEGER NOT NULL DEFAULT 0, rows_created INTEGER NOT NULL DEFAULT 0, rows_updated INTEGER NOT NULL DEFAULT 0, rows_skipped INTEGER NOT NULL DEFAULT 0, error_summary TEXT, started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, finished_at TEXT);
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, details_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_log(entity_type, entity_id);
CREATE INDEX IF NOT EXISTS idx_sync_provider ON external_sync_runs(provider, started_at);
